import {landingRow} from './engine.js';
const colorHex={red:'#FF5268',yellow:'#FFC947'};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="m12 5-7 7 7 7M5 12h14"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3m1-15a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v2"/>',cpu:'<rect x="5" y="5" width="14" height="14" rx="3"/><path d="M9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4"/><rect x="9" y="9" width="6" height="6" rx="1"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5V4m4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',muted:'<path d="m11 4-6 5H2v6h3l6 5V4m5 5 6 6m0-6-6 6"/>',settings:'<path d="m10 3-1 3-3 1-3 1 1 4-1 4 3 1 3 1 1 3h4l1-3 3-1 3-1-1-4 1-4-3-1-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 .5-1 1-1 2m0 3h.01"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',stats:'<path d="M4 20V10m8 10V4m8 16v-7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',swap:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',play:'<path d="m8 4 13 8-13 8z"/>',pause:'<path d="M8 5v14M16 5v14"/>',undo:'<path d="m8 3-5 5 5 5M3 8h10a7 7 0 0 1 0 14"/>',restart:'<path d="M3 9a9 9 0 1 1 0 7m0-13v6h6"/>',trophy:'<path d="M7 3h10v6a5 5 0 0 1-10 0V3m0 2H3v3a5 5 0 0 0 5 5m9-8h4v3a5 5 0 0 1-5 5m-4 1v7m-4 0h8"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',keyboard:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M6 9h.01M10 9h.01M14 9h.01M18 9h.01M6 12h.01M10 12h.01M14 12h.01M18 12h.01M7 16h10"/>',flag:'<path d="M5 22V3m0 1c5-5 9 5 14 0v10c-5 5-9-5-14 0"/>',disc:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>'})[name]??''}</svg>`;
export function logo(){return `<svg class="brand-mark" viewBox="0 0 52 38" aria-hidden="true"><path d="M7 30 45 8" stroke="currentColor" stroke-width="6"/><g fill="currentColor" stroke="var(--bg)" stroke-width="2.8"><circle cx="7" cy="30" r="6.5"/><circle cx="20" cy="22.5" r="6.5"/><circle cx="32.5" cy="15" r="6.5"/><circle cx="45" cy="8" r="6.5"/></g></svg>`;}
export function discMarkup(x,y,color,id,markers,extra=''){return `<g class="disc ${extra}" ${id?`id="${id}"`:''}><circle cx="${x}" cy="${y+1}" r="37.2" fill="#000" opacity=".32"/><circle cx="${x}" cy="${y}" r="35.8" fill="url(#disc-${color})" stroke="${color==='red'?'#ff8190':'#ffdf88'}" stroke-width="1.4"/><circle cx="${x}" cy="${y}" r="27" fill="none" stroke="${color==='red'?'#9c1d34':'#a86511'}" stroke-width="1.7" opacity=".48"/><circle cx="${x}" cy="${y-1}" r="25" fill="none" stroke="#fff" stroke-width="1" opacity=".16"/><path d="M${x-19} ${y-24}Q${x} ${y-34} ${x+18} ${y-24}" stroke="#fff" stroke-width="2.6" stroke-linecap="round" opacity=".3"/>${markers?(color==='red'?`<circle cx="${x}" cy="${y}" r="6" fill="#6d1730" opacity=".6"/>`:`<path d="m${x} ${y-8} 8 8-8 8-8-8z" fill="#835013" opacity=".6"/>`):''}</g>`;}
export function boardSVG({board,colors=['red','yellow'],lines=[],markers=true,winLine=true,active=0,hover=-1,preview=false,fallIndex=-1,decorative=false}){const union=new Set(lines.flat());let holes='',edges='',discs='';for(let r=0;r<6;r++)for(let c=0;c<7;c++){const i=r*7+c,x=70+c*100,y=120+r*100;holes+=`<circle cx="${x}" cy="${y}" r="39" fill="black"/>`;edges+=`<circle cx="${x}" cy="${y}" r="39.7" fill="none" stroke="#92b5ff" stroke-opacity=".2" stroke-width="1.8"/><path d="M${x-37} ${y-8}a38 38 0 0 1 74 0" fill="none" stroke="#062273" stroke-opacity=".85" stroke-width="3"/>`;if(board[i]>=0)discs+=`<g opacity="${union.size&&!union.has(i)?'.38':'1'}">${discMarkup(x,y,colors[board[i]],i===fallIndex?'falling-disc':null,markers,union.has(i)?'winner-disc':'')}</g>`;}
const pr=hover>=0?landingRow(board,hover):-1;return `<svg class="board-svg" viewBox="0 0 740 718" ${decorative?'aria-hidden="true"':'role="img" aria-label="Connect Four board, 7 columns and 6 rows"'}><defs><linearGradient id="board-material" x1="0" y1="0" x2=".8" y2="1"><stop stop-color="#4076f0"/><stop offset=".4" stop-color="#2558cf"/><stop offset="1" stop-color="#183d9b"/></linearGradient><radialGradient id="disc-red" cx=".32" cy=".2" r=".9"><stop stop-color="#ff8996"/><stop offset=".4" stop-color="#ff5268"/><stop offset="1" stop-color="#bc233f"/></radialGradient><radialGradient id="disc-yellow" cx=".32" cy=".2" r=".9"><stop stop-color="#ffe9a2"/><stop offset=".4" stop-color="#ffc947"/><stop offset="1" stop-color="#d18c1a"/></radialGradient><linearGradient id="well" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#061025"/><stop offset="1" stop-color="#0d2147"/></linearGradient><mask id="board-holes"><rect x="20" y="70" width="700" height="600" rx="30" fill="white"/>${holes}</mask><filter id="line-glow" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="7"/></filter></defs><ellipse cx="370" cy="703" rx="322" ry="12" fill="#000" opacity=".35"/><path d="M34 660h672v18a14 14 0 0 1-14 14H48a14 14 0 0 1-14-14z" fill="#0c2464"/><rect x="20" y="79" width="700" height="600" rx="30" fill="#0b2a7c"/><rect x="21" y="71" width="698" height="598" rx="30" fill="url(#well)"/><g id="disc-layer">${discs}</g><g id="preview-layer">${preview&&pr>=0?`<g opacity=".28">${discMarkup(70+hover*100,120+pr*100,colors[active],null,markers)}</g>`:''}</g><rect x="20" y="70" width="700" height="600" rx="30" fill="url(#board-material)" mask="url(#board-holes)"/><rect x="20.8" y="70.8" width="698.4" height="598.4" rx="29.2" fill="none" stroke="#9cbfff" stroke-opacity=".38" stroke-width="1.6"/>${edges}<g id="column-glow">${preview&&pr>=0?`<rect x="${23+hover*100}" y="73" width="94" height="594" rx="25" fill="white" opacity=".055"/>`:''}</g><g id="top-preview">${preview&&pr>=0?`<g opacity=".85" transform="translate(${70+hover*100} 25) scale(.55) translate(${-70-hover*100} -25)">${discMarkup(70+hover*100,25,colors[active],null,markers)}</g>`:''}</g>${winLine?lines.map(line=>{const a=line[0],b=line[3],x1=70+a%7*100,y1=120+Math.floor(a/7)*100,x2=70+b%7*100,y2=120+Math.floor(b/7)*100;return `<path class="winning-line glow" d="M${x1} ${y1}L${x2} ${y2}" stroke="${colorHex[colors[board[a]]]}" stroke-width="18" filter="url(#line-glow)"/><path class="winning-line" d="M${x1} ${y1}L${x2} ${y2}" stroke="#fff6da" stroke-width="4" stroke-linecap="round" pathLength="1"/>`;}).join(''):''}${[...union].map(i=>`<circle class="winning-ring" cx="${70+i%7*100}" cy="${120+Math.floor(i/7)*100}" r="36" fill="none" stroke="#fff6da" stroke-opacity=".9" stroke-width="2"/>`).join('')}<path d="M31 680h678" stroke="#5e88ec" stroke-opacity=".45" stroke-width="1.5"/><rect x="66" y="688" width="72" height="12" rx="6" fill="#142d65"/><rect x="602" y="688" width="72" height="12" rx="6" fill="#142d65"/></svg>`;}
